"""Teaching copy for the local-assistant extension; no network actions."""


def extend(lessons, profiles, step, profile, setup):
    setup = step("Prepare the browser and local-service tools", "import sys",
                 "The runtime check installs browser-compatible map and plotting packages only in Pyodide. Imports expose the local helper functions. No network request to Ollama occurs in this setup cell.",
                 "Plotting, map-building and optional local-model functions are ready.",
                 "Which packages render a map, and which helper will contact Ollama only when explicitly called?")
    lessons.update({
        "18": [setup,
            step("Check the local boundary", "LIVE_CONNECT", "The Boolean switch prevents an automatic request. `await` lets the browser wait without synchronous requests. The diagnostic returns a status, never a made-up model list.", "Default: not probed. Live: server version and installed model names, or a next step.", "Why can a terminal succeed while the browser reports a network error?"),
            step("Inspect the source before asking AI", "cells = synthetic_cells()", "Two loops created twelve polygon features with invented values. Matplotlib draws their rings and labels; GeoLibre receives the same FeatureCollection. Longitude comes first.", "Twelve labeled cells, with values from 35 to 43. They are not measured temperatures.", "Count values of 39 or more by hand. You should find seven."),
            step("Export a map recipe", "project = native_project.to_project()", "The project dictionary stores the layer and camera. `json.dumps` serializes it; `Path` writes into the notebook's own filesystem. The full GeoLibre link in the next section opens a separate workspace.", "A local JSON export and instructions for GeoLibre's native chat panel.", "Open the full app and compare its layer count with the source, before sending a prompt.")],
        "19": [setup,
            step("Ask for a small, typed plan", "LIVE_MODEL", "The default branch labels a hand-authored example. Only the live branch calls local Ollama. The helper sends a schema, checks the installed model, rejects remote-backed models, and clears stale results before a retry.", "A four-field plan and an explicit fixture/live provenance label.", "Find which line makes the actual model request. Why is this not model training in Pyodide?"),
            step("Preview with deterministic code", "plan = validate_plan", "Independent validation rejects unknown fields and unsafe values. The list of selected IDs is computed from the invented grid, not supplied by the language model. The chart is a dry run.", "Seven selected cells for the supplied cutoff of 39.", "Check each requested setting. Could valid JSON still describe the wrong map?"),
            step("Approve this proposal", "APPROVE_MAP", "A separate Boolean gate controls application. `approved_map=None` clears a previous result. The helper uses known GeoLibre operations, not model-generated Python or SQL.", "Default: no map applied. After review and approval: a new GeoLibre map.", "Change the prompt, rerun, and review again before approving. Approval is not a permanent trust decision."),
            step("Preserve a small audit", "audit =", "The audit records provenance, prompt, plan, computed IDs and approval state. The map project is exported only if one was approved. These files stay local until you download or share them.", "An inspectable JSON record; no automatic upload.", "What would you remove before sharing an audit of a real project?")],
        "20": [setup,
            step("Carry forward checked state", "baseline =", "The follow-up includes a validated previous plan. It requests two changes: raise the cutoff and flatten the view. Live errors stop the cell; the fixture is a separate, explicit default.", "Before and after settings, with the response source named.", "Which two fields should remain unchanged?"),
            step("Compare computed evidence", "before_ids =", "Sets make membership and differences explicit. The checks compare the model's settings with an independently authored expected answer. The bar height is a computed feature count, not an estimate of people.", "Seven cells before and four after for the supplied task.", "If counts match but color does not, did the assistant follow the whole request?"),
            step("Try plans that must fail", "invalid_plans =", "Each test adds an unknown URL, non-finite number, invalid camera angle or invented layer. `try/except` shows rejection without stopping the entire lesson. A separate test exercises the human approval gate.", "Four rejected plans and one blocked application.", "Why does checking a schema help without proving the remaining plan is scientifically appropriate?"),
            step("Keep judgment human", "review =", "A dictionary turns evidence and open questions into a review card. The seven perspectives are authored discussion prompts. No extra models are called and no consensus is manufactured.", "A local evidence card that explicitly withholds operational approval.", "Identify a question that needs community knowledge rather than another model response.")],
    })
    profiles.update({
        "18": profile("Local AI, browser map", "Where does the model run when GeoLibre chats?",
            "Local-model setup and native GeoLibre practice; no model is trained in this notebook.",
            "Pyodide prepares a synthetic project. The full GeoLibre web app can call a separate desktop Ollama service after explicit setup.",
            "A visible runtime boundary helps learners see which component holds the map, runs inference and needs permission.",
            [("Inspect", "len(cells['features'])", "Check twelve invented polygons before asking an assistant about them."),
             ("Connect", "LIVE_CONNECT = True", "Opt into a local-service check after configuring exact origins."),
             ("Open", "native_project.to_project()", "Move a reviewed map recipe into the full GeoLibre web app."),
             ("Verify", "heat_proxy_c >= 39", "Check seven selected cells against the native assistant's transcript.")],
            ["Is the model running inside this map?", "No. The browser calls Ollama on this computer.", "I will check both the service and browser permission."],
            "Does local inference mean every map request stays offline?",
            "No. Basemaps, remote layers and the hosted viewer still use the network. Optional hosted AI services must also be considered.", "runtime"),
        "19": profile("A chat request becomes a plan", "Can we inspect the map before applying AI's proposal?",
            "Optional local language-model inference; an authored fixture is used unless live mode is selected.",
            "Ollama proposes four settings. Python checks them and computes selections; GeoLibre renders only after human approval.",
            "Restricting the vocabulary makes proposed changes inspectable and mistakes easier to explain to a new learner.",
            [("Ask", "await propose_map(prompt)", "Request a small JSON plan from an explicitly selected local model."),
             ("Check", "validate_plan(proposal['plan'])", "Reject extra fields, imaginary layers and invalid values."),
             ("Preview", "preview_plan(plan)", "Compute selection IDs without changing an existing map."),
             ("Approve", "APPROVE_MAP = True", "Apply only after comparing the proposal with the intended request.")],
            ["Valid JSON means the AI understood me?", "It may still choose the wrong valid settings.", "I will compare the dry run with my request."],
            "Who calculates the selected-cell count: the model or Python?",
            "Python calculates it from the actual fixture. The model proposes parameters; the human checks their meaning.", "threshold"),
        "20": profile("From chat to checked evidence", "What changed, and what can we responsibly conclude?",
            "A follow-up planning exercise plus deterministic checks and human review; not a world model or clinical system.",
            "Python compares feature sets and rejects invalid plans. A local Ollama follow-up is optional and clearly labeled.",
            "An evidence card connects a map operation to provenance, limits, alternatives and a named human review step.",
            [("Revise", "current_plan=baseline", "Give the assistant only the checked state needed for a follow-up."),
             ("Compare", "after_ids <= before_ids", "Inspect membership as well as the seven-to-four count change."),
             ("Challenge", "validate_plan(candidate)", "Demonstrate rejection of unknown layers, URLs and unsafe values."),
             ("Reflect", "human_approved_for_operational_use", "Record evidence and disagreement without pretending to validate a health model.")],
            ["Four selected cells means four risky communities?", "No. These are invented cells and a chosen filter.", "We need real evidence and people to judge its use."],
            "Does seven perspectives mean seven independent AI evaluations?",
            "No. The card contains authored prompts for people. It neither runs seven agents nor substitutes for external validation.", "hats"),
    })
